  "sections": [
    {"offset": {"line": 3, "column": 0}, "map": {"version":3,"sources":["file:///D:/Jose%20(Datos)/Medicina/CEDIAH/Web/apps/web/src/components/content-studio.tsx"],"sourcesContent":["\"use client\";\r\n\r\nimport type { ChangeEvent, FormEvent, KeyboardEvent as ReactKeyboardEvent } from \"react\";\r\nimport { useEffect, useMemo, useRef, useState } from \"react\";\r\nimport Image from \"next/image\";\r\nimport {\r\n  Archive,\r\n  ArrowLeft,\r\n  CaretLeft,\r\n  CaretRight,\r\n  CardsThree,\r\n  Check,\r\n  CheckCircle,\r\n  CloudArrowUp,\r\n  Compass,\r\n  FileArchive,\r\n  FilePdf,\r\n  FileVideo,\r\n  FunnelSimple,\r\n  GraduationCap,\r\n  ImageSquare,\r\n  MagnifyingGlass,\r\n  NotePencil,\r\n  Notebook,\r\n  PlayCircle,\r\n  Plus,\r\n  Question,\r\n  Trash,\r\n  X,\r\n} from \"@phosphor-icons/react\";\r\nimport dynamic from \"next/dynamic\";\r\nimport {\r\n  ContentItemSchema,\r\n  ensureFlashcardIdentity,\r\n  ensureQuestionIdentity,\r\n  normalizeContentLearningIdentity,\r\n  SubjectSchema,\r\n  type ContentAssetUploadResponse,\r\n  type ContentDraft,\r\n  type ContentItem,\r\n  type ContentKind,\r\n  type RichTextDocument,\r\n  type RichTextNode,\r\n  type Subject,\r\n  type ContentStatus,\r\n  type ContentTopic,\r\n  type ContentWorkspaceResponse,\r\n} from \"@cediah/contracts\";\r\nimport { AppShell } from \"./app-shell\";\r\nimport { isPublishedPermittedDraftUpdate } from \"@/lib/content-editing\";\r\nimport { findVideoLinkedGuide, getVideoGuideContent } from \"@/lib/content-guide-links\";\r\nimport { uniqueRegions } from \"@/lib/content-regions\";\r\nimport { useEditorPublicationIndex } from \"@/lib/use-editor-publication-index\";\r\nimport { QuizPanel } from \"./quiz-panel\";\r\nimport { quizFieldIssue, type QuizFieldIssue } from \"@/lib/question-answer\";\r\nimport { TopicSelector } from \"./topic-selector\";\r\nimport { StudioConfirmDialog } from \"./studio-confirm-dialog\";\r\nimport { StudioNameDialog } from \"./studio-name-dialog\";\r\nimport { PlatformToast, type PlatformNotice } from \"./platform-toast\";\r\n\r\nconst GuideEditorScreen = dynamic(\r\n  () => import(\"./guide-editor-screen\").then((module) => module.GuideEditorScreen),\r\n  {\r\n    loading: () => (\r\n      <div className=\"guide-editor-module-loading\" role=\"status\">\r\n        <span className=\"route-loading-indicator\" aria-hidden=\"true\" />\r\n        Preparando el editor de guía…\r\n      </div>\r\n    ),\r\n    ssr: false,\r\n  },\r\n);\r\n\r\ntype Props = { initialWorkspace: ContentWorkspaceResponse };\r\ntype Asset = NonNullable<ContentItem[\"asset\"]>;\r\ntype GuideItem = Extract<ContentItem, { kind: \"guide\" }>;\r\ntype VideoDraft = Extract<ContentDraft, { kind: \"video\" }>;\r\ntype Mime = ContentAssetUploadResponse[\"asset\"][\"mimeType\"];\r\ntype QuizFocusRequest = { issue: QuizFieldIssue; sequence: number };\r\ntype TargetStatus = Exclude<ContentStatus, \"draft\">;\r\ntype GuideEditorReturnContext = {\r\n  draft: VideoDraft;\r\n  editingId: string;\r\n  file: File | null;\r\n  progress: number;\r\n};\r\ntype Base = Pick<\r\n  ContentDraft,\r\n  \"estimatedMinutes\" | \"featured\" | \"slug\" | \"subjectIds\" | \"summary\" | \"title\" | \"topic\"\r\n  | \"catalogVisibility\"\r\n>;\r\n\r\nconst kinds: { label: string; value: ContentKind }[] = [\r\n  { label: \"Video\", value: \"video\" },\r\n  { label: \"Guía\", value: \"guide\" },\r\n  { label: \"Cuestionario\", value: \"quiz\" },\r\n  { label: \"Flashcards\", value: \"flashcards\" },\r\n  { label: \"Tema\", value: \"topic\" },\r\n];\r\n\r\nconst primaryKinds = [\r\n  { label: \"Guía\", value: \"guide\" },\r\n  { label: \"Cuestionario\", value: \"quiz\" },\r\n  { label: \"Flashcards\", value: \"flashcards\" },\r\n  { label: \"Tema\", value: \"topic\" },\r\n] satisfies { label: string; value: ContentKind }[];\r\n\r\n// Non-video editorial assets stay disabled until they have an independent\r\n// storage provider. The private video test uses its own isolated flow.\r\nconst contentAssetUploadsEnabled = false;\r\nconst defaultVideoCover = \"/anatomy/video-cover-default.png\";\r\nconst maxCoverSourceBytes = 8_000_000;\r\nconst maxEmbeddedCoverBytes = 340_000;\r\n\r\nconst kindIcons: Record<ContentKind, typeof PlayCircle> = {\r\n  flashcards: CardsThree,\r\n  guide: Notebook,\r\n  quiz: Question,\r\n  topic: Compass,\r\n  video: PlayCircle,\r\n};\r\n\r\nconst statuses: { label: string; value: ContentStatus }[] = [\r\n  { label: \"Borrador\", value: \"draft\" },\r\n  { label: \"En revisión\", value: \"in_review\" },\r\n  { label: \"Cambios solicitados\", value: \"changes_requested\" },\r\n  { label: \"Aprobado\", value: \"approved\" },\r\n  { label: \"Publicado\", value: \"published\" },\r\n  { label: \"Archivado\", value: \"archived\" },\r\n];\r\n\r\nconst errors: Record<string, string> = {\r\n  content_conflict: \"No se completó la acción porque el contenido cambió o el enlace ya está en uso. Actualiza la página y, si persiste, cambia el título o el slug antes de guardar.\",\r\n  content_not_publishable: \"El contenido todavía no cumple los requisitos de publicación. Completa los elementos pendientes indicados en la preparación del contenido y vuelve a intentarlo.\",\r\n  content_unavailable: \"El servicio editorial no respondió correctamente. Comprueba tu conexión, actualiza la página y vuelve a intentarlo.\",\r\n  forbidden: \"Tu cuenta no tiene permiso para realizar esta acción. Solicita acceso a coordinación o administración.\",\r\n  identity_unavailable: \"No pudimos validar tu sesión. Vuelve a iniciar sesión y repite la acción.\",\r\n  invalid_content: \"Hay campos obligatorios vacíos o con un formato no válido. Revisa los campos señalados y sus límites antes de guardar.\",\r\n  invalid_content_asset: \"El archivo no cumple los requisitos de formato o tamaño. Selecciona un archivo compatible y vuelve a intentarlo.\",\r\n  invalid_content_transition: \"No se puede aplicar ese cambio desde el estado actual. Guarda primero y sigue el orden de revisión, aprobación y publicación.\",\r\n  not_found: \"El contenido ya no existe o no está disponible para tu cuenta. Actualiza la página o solicita acceso a administración.\",\r\n  unauthorized: \"Tu sesión terminó. Inicia sesión de nuevo para continuar.\",\r\n  invalid_subject: \"El nombre de la materia está vacío o no es válido. Escribe un nombre más corto y vuelve a intentarlo.\",\r\n  subject_conflict: \"Ya existe una materia con ese nombre. Selecciona la existente o utiliza un nombre distinto.\",\r\n};\r\n\r\nfunction labelOf<T extends string>(options: { label: string; value: T }[], value: T) {\r\n  return options.find((option) => option.value === value)?.label ?? value;\r\n}\r\n\r\nfunction slugify(value: string) {\r\n  return value\r\n    .normalize(\"NFD\")\r\n    .replace(/\\p{Diacritic}/gu, \"\")\r\n    .toLowerCase()\r\n    .replace(/[^a-z0-9]+/g, \"-\")\r\n    .replace(/^-+|-+$/g, \"\");\r\n}\r\n\r\nfunction normalizeSearch(value: string) {\r\n  return value\r\n    .normalize(\"NFD\")\r\n    .replace(/\\p{Diacritic}/gu, \"\")\r\n    .toLocaleLowerCase(\"es\");\r\n}\r\n\r\nfunction topicsForSubjects(\r\n  items: ContentItem[],\r\n  taxonomyTopics: ContentTopic[],\r\n  subjectIds: readonly string[],\r\n  requireEverySubject: boolean,\r\n) {\r\n  if (subjectIds.length === 0) return [];\r\n  const selected = new Set(subjectIds);\r\n  const matchesSubjects = (candidateSubjectIds: readonly string[]) =>\r\n    requireEverySubject\r\n      ? subjectIds.every((id) => candidateSubjectIds.includes(id))\r\n      : candidateSubjectIds.some((id) => selected.has(id));\r\n  return uniqueRegions([\r\n    ...taxonomyTopics\r\n      .filter((topic) => matchesSubjects(topic.subjectIds))\r\n      .map((topic) => topic.name),\r\n    ...items\r\n      .filter((current) => matchesSubjects(current.subjectIds))\r\n      .flatMap((current) => current.content.regions.length > 0\r\n        ? current.content.regions\r\n        : [current.topic]),\r\n  ])\r\n    .sort((left, right) => left.localeCompare(right, \"es\"));\r\n}\r\n\r\nfunction summaryFromText(value: string) {\r\n  const compact = value.replace(/\\s+/g, \" \").trim();\r\n  return compact.length > 280 ? compact.slice(0, 277).trimEnd() + \"…\" : compact;\r\n}\r\n\r\nfunction richTextNodeHasBody(node: RichTextNode, insideHeading = false): boolean {\r\n  const nextInsideHeading = insideHeading || node.type === \"heading\";\r\n  if (node.type === \"text\") return !nextInsideHeading && node.text.trim().length > 0;\r\n  if (\"content\" in node && node.content) {\r\n    return node.content.some((child) => richTextNodeHasBody(child, nextInsideHeading));\r\n  }\r\n  return false;\r\n}\r\n\r\nfunction richTextDocumentHasBody(document: RichTextDocument | null): boolean {\r\n  return Boolean(document?.content.some((node) => richTextNodeHasBody(node)));\r\n}\r\n\r\nfunction prepareDraft(draft: ContentDraft): ContentDraft {\r\n  const slug = draft.slug || slugify(draft.title) || `contenido-${Date.now().toString(36)}`;\r\n  const regions = uniqueRegions(\r\n    draft.content.regions.length > 0 ? draft.content.regions : [draft.topic],\r\n  );\r\n  const topic = regions[0] ?? draft.topic;\r\n\r\n  if (draft.kind === \"video\") {\r\n    return {\r\n      ...draft,\r\n      slug,\r\n      subjectIds: Array.from(new Set(draft.subjectIds)),\r\n      topic,\r\n      content: {\r\n        ...draft.content,\r\n        description: draft.content.description.trim() || draft.summary.trim(),\r\n        regions,\r\n      },\r\n    };\r\n  }\r\n  return {\r\n    ...draft,\r\n    slug,\r\n    subjectIds: Array.from(new Set(draft.subjectIds)),\r\n    topic,\r\n    content: { ...draft.content, regions },\r\n  } as ContentDraft;\r\n}\r\n\r\nfunction emptyDraft(kind: ContentKind, seed: Partial<Base> = {}): ContentDraft {\r\n  const base: Base = {\r\n    catalogVisibility: \"catalog\",\r\n    estimatedMinutes: null,\r\n    featured: false,\r\n    slug: \"\",\r\n    summary: \"\",\r\n    subjectIds: [],\r\n    title: \"\",\r\n    topic: \"\",\r\n    ...seed,\r\n  };\r\n\r\n  if (kind === \"video\") {\r\n    return {\r\n      ...base,\r\n      kind,\r\n      content: {\r\n        coverImageUrl: null,\r\n        description: \"\",\r\n        durationSeconds: null,\r\n        externalUrl: null,\r\n        guide: { document: null, sections: [] },\r\n        keyPoints: [],\r\n        quiz: { questions: [] },\r\n        regions: [],\r\n      },\r\n    };\r\n  }\r\n  if (kind === \"guide\") {\r\n    return {\r\n      ...base,\r\n      kind,\r\n      content: {\r\n        document: null,\r\n        keyPoints: [],\r\n        linkedVideoId: null,\r\n        quiz: { questions: [] },\r\n        regions: [],\r\n        sections: [],\r\n      },\r\n    };\r\n  }\r\n  if (kind === \"quiz\") {\r\n    const question = ensureQuestionIdentity(\r\n      { correctOptionIndex: 0, explanation: \"\", options: [\"\", \"\"], prompt: \"\" },\r\n      () => crypto.randomUUID(),\r\n    ).value;\r\n    return {\r\n      ...base,\r\n      kind,\r\n      content: {\r\n        questions: [question],\r\n        regions: [],\r\n      },\r\n    };\r\n  }\r\n  if (kind === \"flashcards\") {\r\n    const card = ensureFlashcardIdentity(\r\n      { back: \"\", front: \"\" },\r\n      () => crypto.randomUUID(),\r\n    ).value;\r\n    return { ...base, kind, content: { cards: [card], regions: [] } };\r\n  }\r\n  return { ...base, kind: \"topic\", content: { introduction: \"\", objectives: [], regions: [] } };\r\n}\r\n\r\nfunction canvasBlob(canvas: HTMLCanvasElement, quality: number) {\r\n  return new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, \"image/webp\", quality));\r\n}\r\n\r\nfunction blobDataUrl(blob: Blob) {\r\n  return new Promise<string>((resolve, reject) => {\r\n    const reader = new FileReader();\r\n    reader.onerror = () => reject(new Error(\"No se pudo leer la imagen seleccionada.\"));\r\n    reader.onload = () => typeof reader.result === \"string\"\r\n      ? resolve(reader.result)\r\n      : reject(new Error(\"No se pudo preparar la imagen seleccionada.\"));\r\n    reader.readAsDataURL(blob);\r\n  });\r\n}\r\n\r\nasync function prepareVideoCover(file: File) {\r\n  if (![\"image/jpeg\", \"image/png\", \"image/webp\"].includes(file.type)) {\r\n    throw new Error(\"La portada debe ser JPG, PNG o WebP. Selecciona una imagen en uno de esos formatos.\");\r\n  }\r\n  if (file.size > maxCoverSourceBytes) {\r\n    throw new Error(\"La portada supera 8 MB. Reduce el tamaño del archivo y vuelve a intentarlo.\");\r\n  }\r\n\r\n  const sourceUrl = URL.createObjectURL(file);\r\n  try {\r\n    const source = document.createElement(\"img\");\r\n    source.decoding = \"async\";\r\n    source.src = sourceUrl;\r\n    try {\r\n      await source.decode();\r\n    } catch {\r\n      throw new Error(\"No pudimos abrir la portada. Comprueba que sea una imagen JPG, PNG o WebP válida y vuelve a seleccionarla.\");\r\n    }\r\n\r\n    const scale = Math.min(1, 1280 / source.naturalWidth, 720 / source.naturalHeight);\r\n    const canvas = document.createElement(\"canvas\");\r\n    canvas.width = Math.max(1, Math.round(source.naturalWidth * scale));\r\n    canvas.height = Math.max(1, Math.round(source.naturalHeight * scale));\r\n    const context = canvas.getContext(\"2d\", { alpha: false });\r\n    if (!context) throw new Error(\"El navegador no pudo procesar la portada. Prueba con otra imagen.\");\r\n    context.fillStyle = \"#0f172a\";\r\n    context.fillRect(0, 0, canvas.width, canvas.height);\r\n    context.drawImage(source, 0, 0, canvas.width, canvas.height);\r\n\r\n    let blob: Blob | null = null;\r\n    for (const quality of [0.82, 0.72, 0.62, 0.52]) {\r\n      blob = await canvasBlob(canvas, quality);\r\n      if (blob && blob.size <= maxEmbeddedCoverBytes) break;\r\n    }\r\n    if (!blob || blob.size > maxEmbeddedCoverBytes) {\r\n      throw new Error(\"La portada sigue siendo demasiado pesada. Usa una imagen más sencilla o de menor resolución.\");\r\n    }\r\n    return blobDataUrl(blob);\r\n  } finally {\r\n    URL.revokeObjectURL(sourceUrl);\r\n  }\r\n}\r\n\r\nfunction itemDraft(item: ContentItem): ContentDraft {\r\n  const draft = structuredClone(item) as unknown as Record<string, unknown>;\r\n  for (const key of [\r\n    \"asset\",\r\n    \"authorUserId\",\r\n    \"createdAt\",\r\n    \"id\",\r\n    \"publishedAt\",\r\n    \"status\",\r\n    \"updatedAt\",\r\n  ]) {\r\n    delete draft[key];\r\n  }\r\n  return normalizeContentLearningIdentity(\r\n    draft as ContentDraft,\r\n    () => crypto.randomUUID(),\r\n  ).value;\r\n}\r\n\r\nasync function json<T>(url: string, init: RequestInit = {}) {\r\n  const headers = new Headers(init.headers);\r\n  if (init.body !== undefined) headers.set(\"Content-Type\", \"application/json\");\r\n  const response = await fetch(url, { ...init, cache: \"no-store\", headers });\r\n  const body: unknown = await response\r\n    .json()\r\n    .catch(() => ({ error: \"content_unavailable\" }));\r\n\r\n  if (!response.ok) {\r\n    const code =\r\n      body && typeof body === \"object\" && \"error\" in body && typeof body.error === \"string\"\r\n        ? body.error\r\n        : \"content_unavailable\";\r\n    throw new Error(errors[code] ?? `No fue posible completar la acción (${response.status}).`);\r\n  }\r\n  return body as T;\r\n}\r\n\r\nasync function contentItemJson(url: string, init: RequestInit = {}) {\r\n  const parsed = ContentItemSchema.safeParse(await json<unknown>(url, init));\r\n  if (!parsed.success) throw new Error(errors.content_unavailable);\r\n  return parsed.data;\r\n}\r\n\r\nfunction onlySubjectAssignmentChanged(current: ContentDraft, baseline: ContentDraft) {\r\n  if (JSON.stringify(current.subjectIds) === JSON.stringify(baseline.subjectIds)) return false;\r\n  const currentWithoutSubjects = { ...current, subjectIds: [] };\r\n  const baselineWithoutSubjects = { ...baseline, subjectIds: [] };\r\n  return JSON.stringify(currentWithoutSubjects) === JSON.stringify(baselineW